(()=>{
  'use strict';
  if(!/^\/lab(?:\/|$)/.test(location.pathname)) return;
  const api=async(url,opt={})=>{const r=await fetch(url,{credentials:'same-origin',...opt,headers:{'x-photobridge-portal':'lab',...(opt.body?{'content-type':'application/json'}:{}),...(opt.headers||{})}});let d=null;try{d=await r.json()}catch{}if(!r.ok)throw Object.assign(new Error(d?.error||'request_failed'),{status:r.status,...(d||{})});return d};
  const css=`#pb904r7LabActivation{position:fixed;z-index:7900;right:16px;bottom:18px;width:min(520px,calc(100vw - 32px));box-sizing:border-box;padding:13px 14px;border:1px solid #c7d7fe;border-radius:15px;background:linear-gradient(135deg,#f5f8ff,#fff);box-shadow:0 12px 38px rgba(15,23,42,.16);direction:rtl;font-family:Vazirmatn,Tahoma,Arial,sans-serif;color:#344054}#pb904r7LabActivation[hidden]{display:none!important}#pb904r7LabActivation .row{display:flex;align-items:center;justify-content:space-between;gap:12px}#pb904r7LabActivation .copy{display:grid;gap:4px;min-width:0}#pb904r7LabActivation .state{width:max-content;padding:4px 9px;border-radius:999px;background:#fff7ed;color:#c2410c;font-size:10px;font-weight:900}#pb904r7LabActivation .state.pending{background:#eff6ff;color:#1d4ed8}#pb904r7LabActivation .state.rejected{background:#fff1f2;color:#b42318}#pb904r7LabActivation b{font-size:13px}#pb904r7LabActivation p{margin:0;color:#667085;font-size:10px;line-height:1.9}#pb904r7LabActivation button{flex:0 0 auto;border:0;border-radius:10px;background:#315efb;color:#fff;padding:10px 13px;font:900 10px Vazirmatn,Tahoma,Arial,sans-serif;cursor:pointer}#pb904r7LabActivation .msg{font-size:9px;margin-top:6px;color:#047857}@media(max-width:700px){#pb904r7LabActivation{right:8px;bottom:78px;width:calc(100vw - 16px);padding:11px}#pb904r7LabActivation .row{align-items:stretch;flex-direction:column}#pb904r7LabActivation button{width:100%}}`;
  const style=document.createElement('style');style.textContent=css;document.head.appendChild(style);
  const box=document.createElement('section');box.id='pb904r7LabActivation';box.hidden=true;box.innerHTML='<div class="row"><div class="copy"><span class="state">در حال تکمیل</span><b>فعال‌سازی لابراتوار</b><p></p></div><button type="button">ارسال درخواست فعال‌سازی</button></div><div class="msg"></div>';document.body.appendChild(box);
  const state=box.querySelector('.state'),title=box.querySelector('b'),text=box.querySelector('p'),btn=box.querySelector('button'),msg=box.querySelector('.msg');
  let current=null;
  function render(a){current=a||{};const st=String(current.activation_status||'approved'),approved=Boolean(current.active)&&st==='approved';box.hidden=approved;if(approved)return;state.className='state';btn.hidden=false;msg.textContent='';if(st==='requested'){state.textContent='در انتظار بررسی';state.classList.add('pending');title.textContent='درخواست فعال‌سازی ارسال شده';text.textContent='ادمین PhotoBridge اطلاعات و قیمت‌های لابراتوار را بررسی می‌کند. تا زمان تأیید، لابراتوار در فهرست عمومی نمایش داده نمی‌شود.';btn.hidden=true}else if(st==='rejected'){state.textContent='نیازمند اصلاح';state.classList.add('rejected');title.textContent='درخواست نیاز به اصلاح دارد';text.textContent=current.activation_review_note?'نظر ادمین: '+current.activation_review_note+' — اصلاحات را انجام بده و دوباره درخواست بفرست.':'اصلاحات لازم را انجام بده و دوباره درخواست فعال‌سازی بفرست.';btn.textContent='ارسال دوباره درخواست'}else{state.textContent='در حال تکمیل';title.textContent='لابراتوار هنوز عمومی نشده';text.textContent='تنظیمات، خدمات و قیمت‌ها را کامل کن؛ بعد درخواست فعال‌سازی را برای ادمین PhotoBridge بفرست.';btn.textContent='ارسال درخواست فعال‌سازی'}}
  async function load(){try{const d=await api('/api/lab/activation-status');render(d.activation)}catch(e){if(e.status===401||e.status===403)box.hidden=true}}
  btn.addEventListener('click',async()=>{btn.disabled=true;msg.textContent='';try{const d=await api('/api/lab/activation-request',{method:'POST',body:'{}'});render(d.activation);msg.textContent='درخواست برای ادمین PhotoBridge ارسال شد.'}catch(e){msg.style.color='#b42318';msg.textContent=e.error==='already_activated'?'لابراتوار از قبل فعال است.':'ارسال درخواست انجام نشد.'}finally{btn.disabled=false}});
  if(document.readyState==='loading')document.addEventListener('DOMContentLoaded',()=>setTimeout(load,500),{once:true});else setTimeout(load,500);
  window.addEventListener('focus',()=>setTimeout(load,300));
})();
